css:
.resume{--primary: #1e3a5f;    
      --accent: #2c5f2d;     
      --body-text: #1f2a3a;
      --light-bg: #f8fafc;
      --divider: #d1d9e0;
      --tag-bg: #e9edf2;
      --tag-text: #1e3a5f;
      --white: #ffffff;
      --print-black: #000000;}
.resume{width: 100%;
      padding: 0.7in 0.7in 0.6in 0.7in;
      background: white;}
.resume h1, .resume h2, .resume h3, .resume p, .resume li, .resume span, .resume div{font-weight: normal;}
.name-section{margin-bottom: 28px;
      border-bottom: 2px solid var(--primary);
      padding-bottom: 16px;}
.name{font-size: 2.4rem;
      font-weight: 700;
      letter-spacing: 0.5px;
      color: var(--primary);
      margin-bottom: 6px;
      line-height: 1.2;
      font-family: 'Arial', 'Helvetica Neue', 'Calibri', '思源黑体', sans-serif;}
.title-tagline{font-size: 1.1rem;
      font-weight: 400;
      color: #2d3a4a;
      display: flex;
      flex-wrap: wrap;
      gap: 18px;
      margin-top: 4px;
      align-items: center;}
.title-tagline span{display: inline-flex;
      align-items: center;
      gap: 4px;}
.contact-row{margin-top: 12px;
      font-size: 0.9rem;
      color: #334155;
      display: flex;
      flex-wrap: wrap;
      gap: 18px;
      align-items: center;}
.contact-item{display: inline-flex;
      align-items: center;
      gap: 5px;}
.section-title{font-size: 1rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--primary);
      border-bottom: 1.5px solid var(--divider);
      padding-bottom: 5px;
      margin: 28px 0 14px 0;
      font-family: 'Arial', 'Helvetica Neue', sans-serif;}
.experience-item{margin-bottom: 20px;}
.exp-header{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      margin-bottom: 4px;}
.company-name{font-weight: 700;
      font-size: 1rem;
      color: #0b1c2e;}
.job-title{font-weight: 600;
      color: #1f2a3a;
      margin-left: 8px;
      font-size: 0.95rem;}
.date-location{font-size: 0.85rem;
      color: #4b5563;
      white-space: nowrap;
      text-align: right;}
.description{margin-top: 5px;
      padding-left: 0;
      list-style: none;}
.description li{position: relative;
      padding-left: 18px;
      margin-bottom: 5px;
      font-size: 0.9rem;
      color: #1e293b;
      line-height: 1.5;}
.description li::before{content: "•";
      position: absolute;
      left: 2px;
      color: #2c3e50;
      font-weight: bold;}
.skills-container{display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;}
.skill-tag{background: var(--tag-bg);
      color: var(--tag-text);
      padding: 5px 14px;
      border-radius: 20px;
      font-size: 0.85rem;
      font-weight: 500;
      letter-spacing: 0.2px;
      border: 1px solid #ccd7e4;
      white-space: nowrap;}
.skill-category{font-weight: 700;
      margin-right: 6px;
      color: #0f263b;
      font-size: 0.9rem;}
.two-column-list{display: flex;
      flex-wrap: wrap;
      gap: 8px 30px;
      list-style: none;
      padding-left: 0;
      margin-top: 5px;}
.two-column-list li{width: calc(50% - 15px);
      font-size: 0.9rem;
      position: relative;
      padding-left: 16px;}
.two-column-list li::before{content: "•";
      position: absolute;
      left: 0;
      color: #2c3e50;}
.project-item{margin-bottom: 14px;}
.project-title{font-weight: 700;
      font-size: 0.95rem;
      color: #0f2b44;}
.project-stack{font-size: 0.8rem;
      color: #4b5563;
      margin-left: 10px;
      font-weight: 400;}
.left-accent-bar{border-left: 4px solid var(--primary);
      padding-left: 18px;
      margin-top: 4px;}
.resume hr{border: none;
      border-top: 1px solid var(--divider);
      margin: 16px 0 10px 0;}

.resume{max-width:210mm;margin:0 auto;box-shadow:0 8px 20px rgba(0,0,0,0.08);font-family:Arial,"Helvetica Neue","Calibri","思源黑体","Source Han Sans SC","Noto Sans SC",sans-serif;color:#1f2a3a;line-height:1.5}.resume-title{font-size:9pt;letter-spacing:0.14em;color:#4b5563;margin-bottom:8px}.summary{font-size:0.92rem;color:#1e293b}.skill-block{margin-bottom:10px}.skill-block .skill-category{display:inline-block;margin-bottom:4px}.project-desc{margin-top:3px;font-size:0.88rem;color:#2d3a4a}.edu-row{display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap}.cert-line{display:flex;flex-wrap:wrap;gap:14px;align-items:center}.lang-line{margin-left:auto;font-size:0.9rem}.lang{margin-right:8px}
